import unittest
import click

class AdditionalContracts(unittest.TestCase):
    def test_invoke_does_not_inherit_unpassed_parent_params(self):
        parent = click.Context(click.Command('root'))
        parent.params['unpassed'] = 'parent-only'
        @click.command()
        @click.pass_context
        def child(ctx, **values):
            return dict(ctx.params), values
        self.assertEqual(parent.invoke(child, supplied=3), ({'supplied':3}, {'supplied':3}))

    def test_forward_preserves_keyword_names_cmd_and_self(self):
        parent = click.Context(click.Command('root'))
        @click.command()
        @click.pass_context
        def child(ctx, **values):
            return values
        self.assertEqual(parent.forward(child, cmd='keep', self='also-keep'),
                         {'cmd':'keep', 'self':'also-keep'})

if __name__=='__main__':
    unittest.main(verbosity=2)
